                            wj = ((ofilter * C + c) * K + kr) * K + kc
                            product = snapshot_x[xj] * snapshot_w[wj]
                            if not math.isfinite(product):
                                raise ValueError(
                                    "conv2d_multi intermediate must be"
                                    " finite"
                                )
                            out_data[oi] = out_data[oi] + product
